import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"32、【恆】 巽下震上","description":"周易口訣義 - 32、【恆】 巽下震上","frontmatter":{"title":"32、【恆】 巽下震上","description":"周易口訣義 - 32、【恆】 巽下震上"},"headers":[],"relativePath":"classics/koujueyi/034.md","filePath":"classics/koujueyi/034.md"}'),r={name:"classics/koujueyi/034.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_32、【恆】-巽下震上" tabindex="-1">32、【恆】 巽下震上 <a class="header-anchor" href="#_32、【恆】-巽下震上" aria-label="Permalink to “32、【恆】 巽下震上”">​</a></h1><p>彖曰：「恆」，久也。剛上而柔下，雷風相與，巽而動，剛柔皆應，恆。「恆亨無咎利貞」，久於其道也。天地之道，恆久而不已也。「利有攸往」，終則有始也。日月得天而能久照，四時變化而能久成，聖人久於其道而天下化成。觀其所恆，而天地萬物之情可見矣！象曰：雷風，恆。君子以立不易方。</p><p>初六：浚恆，貞兇，無攸利。</p><p>象曰：「浚恆」之「兇」，始求深也。</p><p>九二：悔亡。</p><p>象曰：九二「悔亡」，能久中也。</p><p>九三：不恆其德，或承之羞，貞吝。</p><p>象曰：「不恆其德」，無所容也。</p><p>九四：田無禽。象曰：久非其位，安得禽也！</p><p>六五：恆其德，貞。婦人吉，夫子兇。</p><p>象曰：「婦人貞吉」，從一而終也；夫子制義，從婦兇也。</p><p>上六，振恆，兇。</p><p>象曰：「振恆」在上，大無功也。</p><p>解讀</p><p>恆亨者，恆，久也；恆久之道，所貴變通，不能變通，無由長久，故繫辭雲「易窮則變，變則通，通則久」是也。「無咎，利貞，利有攸往」者，恆而亨，以濟三事也。謂既變通，即無咎過，故利以修正，正道既行，即何往不利也。象曰：「雷風，恆」，先儒皆雲：雷資風而益遠，風假雷以增威，故「君子以立不易方」者，方，道也；言君子立身修行，舉事合宜，不移其道，宜於世俗也。</p><p>「初六，浚恆，貞兇，無攸利」者，浚，深也；初六處恆之始，即合漸漸以求於恆，而乃浚然使深深為恆，是兇正害德，無施而利，故「貞兇，無攸利」也。</p><p>九二，悔亡。以陽居陰，位既不正，所以有悔，守其謙道，所以「悔亡」也。</p><p>九三「不恆其德，或承之羞，貞吝」者，居下卦之上，即是進慕高位；處上卦之下，又欲靜退自守，故不恆守其一德，是執心不定，德行無恆，即有恥辱至焉。以此為正，亦可賤矣，故「貞吝」也。</p><p>九四：田無禽者，畋獵也，禽，喻有功也。處恆之時，位既不正，即是田獵無所獲，喻有事而無功也。</p><p>六五：恆其德，貞。婦人吉，夫子兇。處恆之時而得尊位，當須普親天下，而乃專志在二，即是執守一德，故曰「恆其德，貞」也。既不能廣親賢德，守一而已，斯乃婦人之道。若譬之丈夫，即致兇災，故「夫子兇」也。</p><p>上六：振恆。兇者，振躁動也。處夫動極，即合安靜，無為無事而已。反以躁動求為，即有兇危及也。</p>',21)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
